head.script:
scwin.onpageload = function() {
	var organizationBasicData = [
		{ "ORG_CD": "010000", "ORG_NM": "조직", "ORG_LEVEL": 1, "ORG_CLASS_CD": "01" },
		{ "ORG_CD": "010100", "ORG_NM": "CEO", "ORG_LEVEL": 2, "ORG_CLASS_CD": "01" },
		{ "ORG_CD": "010200", "ORG_NM": "서비스사업본부", "ORG_LEVEL": 2, "ORG_CLASS_CD": "04" },
		{ "ORG_CD": "010201", "ORG_NM": "서비스사업1팀", "ORG_LEVEL": 3, "ORG_CLASS_CD": "04" },
		{ "ORG_CD": "010202", "ORG_NM": "서비스사업2팀", "ORG_LEVEL": 3, "ORG_CLASS_CD": "04" }
	];
	dlt_organizationBasic.setJSON(organizationBasicData);
	var rowCount = dlt_organizationBasic.getRowCount();
	for (var i = 0; i < rowCount; i++) {
		var orgClassCode = dlt_organizationBasic.getCellData(i, "ORG_CLASS_CD");
		if (orgClassCode == "04") {
			trv_organizationBasic.setLabelStyle(i, "color", "red", false);
		}
	}
};
